try {
    Pattern.compile('[');
    System.assert(false);
} catch (PatternSyntaxException e) {
    System.assertEquals('[', e.getPattern());
    System.assertEquals(-1, e.getIndex());
    System.assert(e.getDescription().contains('missing closing ]'));
    System.assert(e.getMessage().contains('missing closing ]'));
    System.assertEquals('System.PatternSyntaxException', e.getTypeName());
} catch (Exception e) {
    System.assert(false);
}
try {
    Pattern.matches('[', 'x');
    System.assert(false);
} catch (IllegalArgumentException e) {
    System.assertEquals('System.PatternSyntaxException', e.getTypeName());
}
Pattern words = Pattern.compile('([A-Z]+)');
Matcher m = words.matcher('aa ABC bb 123 cc');
System.assert(m.hasAnchoringBounds());
System.assert(!m.hasTransparentBounds());
m.region(3, 9);
System.assertEquals(3, m.regionStart());
System.assertEquals(9, m.regionEnd());
System.assert(m.find());
System.assertEquals('ABC', m.group());
System.assertEquals(1, m.groupCount());
m.useAnchoringBounds(false);
m.useTransparentBounds(true);
System.assert(!m.hasAnchoringBounds());
System.assert(m.hasTransparentBounds());
m.usePattern(Pattern.compile('[0-9]+'));
System.assertEquals(3, m.regionStart());
System.assertEquals(9, m.regionEnd());
System.assert(!m.find());
m.region(10, 13);
System.assert(m.find());
System.assertEquals('123', m.group());

